INSERT INTO `program_categories` VALUES (1,'TUPAD','DOLE\'s Tulong Panghanapbuhay sa Ating Disadvantaged/Displaced Workers (TUPAD) is a community-based package of assistance that provides emergency employment for displaced workers.','- Must be 18 years old and above.\r\n- Must not have availed of the TUPAD program in the last 1 year and 8 months.','- Photo Copy of National ID (back to back)','uploads/programs/prog_1778363380_9fb4a66b.png','Any',18,NULL,1),(2,'SPES','The Special Program for Employment of Students (SPES) aims to provide temporary employment to poor but deserving students during summer and/or Christmas vacation.','- 18 to 30 years of age.\r\n- Enrolled or intending to enroll.\r\n- Combined net income does not exceed poverty threshold.\r\n- Fourth-year college students are not eligible for the PESO Vinzons SPES batch.','- Birth Certificate\r\n- Photocopy of ITR / BIR Tax Exemption / Cert of Low Income\r\nFor student: \r\n- Photo copy of average passing grade of the previous semester or\r\n- Original copy of certification by the school registrat\r\n- Form 137 / 138 (for SHS) or Cert of Grades (for College)\r\n- Certificate of Registration\r\n- Passport-sized picture\r\n- Plastic Envelope','uploads/programs/prog_1778363717_862df7a7.png','Any',18,30,0),(3,'MSME Profiling','The MSME profiling program assesses local businesses to provide targeted livelihood assistance and capacity-building.','- Must be a registered business owner operating within the municipality.','- Any VALID Government-issued ID\r\n- Business Registration Document (DTI / Mayor\'s Permit)','uploads/programs/prog_1778363911_c20c0926.png','Any',18,NULL,0);
/*!40000 ALTER TABLE `program_categories` ENABLE KEYS */;
UNLOCK TABLES;

