INSERT INTO `programs` VALUES (1,'TUPAD-REGULAR-2026-001','TUPAD','Regular TUPAD','DOLE\'s Tulong Panghanapbuhay sa Ating Disadvantaged/Displaced Workers (TUPAD) is a community-based package of assistance that provides emergency employment for displaced workers.','- Must be 18 years old and above.\r\n- Must not have availed of the TUPAD program in the last 1 year and 8 months.','- Photo Copy of National ID (back to back)','2026-05-01','2026-05-31','PESO Vinzons','uploads/programs/prog_1778363380_9fb4a66b.png',100,'Completed','Approved',NULL,NULL,NULL,1,'2026-05-11 09:42:54','2026-09-05 14:20:57','Any',18,NULL,1),(2,'TUPAD-REGULAR-2026-002','TUPAD','Regular TUPAD','DOLE\'s Tulong Panghanapbuhay sa Ating Disadvantaged/Displaced Workers (TUPAD) is a community-based package of assistance that provides emergency employment for displaced workers.','- Must be 18 years old and above.\r\n- Must not have availed of the TUPAD program in the last 1 year and 8 months.','- Photo Copy of National ID (back to back)','2026-05-01','2026-05-31','PESO Vinzons','uploads/programs/prog_1778363380_9fb4a66b.png',10,'Completed','Approved',NULL,NULL,NULL,1,'2026-05-11 10:55:01','2026-08-20 21:25:14','Any',18,NULL,1),(3,'MSME-PROFILING-2026-0001','MSME Profiling',NULL,'The MSME profiling program assesses local businesses to provide targeted livelihood assistance and capacity-building.','- Must be a registered business owner operating within the municipality.','- Any VALID Government-issued ID\r\n- Business Registration Document (DTI / Mayor\'s Permit)','2026-08-01','2026-09-30','PESO Vinzons','uploads/programs/prog_1778363911_c20c0926.png',100,'Ongoing','Approved',NULL,NULL,NULL,1,'2026-08-07 12:01:17','2026-09-03 06:49:44','Any',18,NULL,0),(4,'SPES-2026-001','SPES',NULL,'The Special Program for Employment of Students (SPES) aims to provide temporary employment to poor but deserving students during summer and/or Christmas vacation.','- 18 to 30 years of age.\r\n- Enrolled or intending to enroll.\r\n- Combined net income does not exceed poverty threshold.\r\n- Fourth-year college students are not eligible for the PESO Vinzons SPES batch.','- Birth Certificate\r\n- Photocopy of ITR / BIR Tax Exemption / Cert of Low Income\r\nFor student: \r\n- Photo copy of average passing grade of the previous semester or\r\n- Original copy of certification by the school registrat\r\n- Form 137 / 138 (for SHS) or Cert of Grades (for College)\r\n- Certificate of Registration\r\n- Passport-sized picture\r\n- Plastic Envelope','2026-08-01','2026-09-30','PESO Vinzons','uploads/programs/prog_1778363717_862df7a7.png',100,'Ongoing','Approved',NULL,NULL,NULL,1,'2026-08-07 12:01:37','2026-09-02 15:10:18','Any',18,30,0),(5,'TUPAD-BRIGADA-2026-001','TUPAD','TUPAD Brigada','DOLE\'s Tulong Panghanapbuhay sa Ating Disadvantaged/Displaced Workers (TUPAD) is a community-based package of assistance that provides emergency employment for displaced workers.','- Must be 18 years old and above.\r\n- Must not have availed of the TUPAD program in the last 1 year and 8 months.','- Photo Copy of National ID (back to back)','2026-09-07','2026-09-30','PESO Vinzons','uploads/programs/prog_1778363380_9fb4a66b.png',2,'Ongoing','Approved',NULL,NULL,NULL,2,'2026-08-20 20:56:44','2026-09-10 09:47:53','Any',18,30,1);
